fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // The problem statement guarantees that `a` and `b` have the same length.
    // We assert this to catch misuse in debug builds.
    debug_assert_eq!(a.len(), b.len());

    // Consume `a` and `b`, zip them together, compare element-wise, and collect the results.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x <= y)
     .collect()
}

